# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_program() {
    if [[ -n "$argc__option" ]]; then
        local -n ref="$argc__option"
        argc__positionals=( "${ref[@]}" )
        unset -n ref
    fi
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_ref() {
    git rev-parse --git-dir >/dev/null 2>&1 || return 0
    local git_dir ref
    git_dir=$(git rev-parse --absolute-git-dir 2>/dev/null)
    [[ -n "$git_dir" ]] || return 0
    for ref in HEAD FETCH_HEAD ORIG_HEAD; do
        if [[ -e "$git_dir/$ref" ]]; then
            printf '%s\n' "$ref"
        fi
    done
    git for-each-ref --count=500 --format='%(refname:strip=2)' refs/heads refs/tags refs/remotes 2>/dev/null
}

_choice_remote() {
    git rev-parse --git-dir >/dev/null 2>&1 || return 0
    git remote 2>/dev/null
}
